700	bool CachedReadBufferFromRemoteFS::writeCache(char * data, size_t size, size_t offset, FileSegment & file_segment)
701	{
702	    Stopwatch watch(CLOCK_MONOTONIC);
703	
704	    try
705	    {
706	        file_segment.write(data, size, offset);
707	    }
708	    catch (ErrnoException & e)
709	    {
710	        int code = e.getErrno();
711	        if (code == /* No space left on device */28 || code == /* Quota exceeded */122)
712	        {
713	            LOG_INFO(log, "Insert into cache is skipped due to insufficient disk space. ({})", e.displayText());
714	            return false;
715	        }
716	        throw;
717	    }
718	
719	    watch.stop();
720	    auto elapsed = watch.elapsedMicroseconds();
721	    current_file_segment_counters.increment(ProfileEvents::FileSegmentCacheWriteMicroseconds, elapsed);
722	    ProfileEvents::increment(ProfileEvents::CachedReadBufferCacheWriteMicroseconds, elapsed);
723	    ProfileEvents::increment(ProfileEvents::CachedReadBufferCacheWriteBytes, size);
724	
725	    return true;
726	}
